pub fn heap(nums:&[i32],k:usize)->Vec<i32>{use std::collections::BinaryHeap; if nums.is_empty(){return vec![];} let mut h=BinaryHeap::new(); let mut o=Vec::with_capacity(nums.len()-k+1); for i in 0..nums.len(){h.push((nums[i],i)); if i+1>=k{while h.peek().unwrap().1+k<=i{h.pop();} o.push(h.peek().unwrap().0);}} o}
pub fn deque(nums:&[i32],k:usize)->Vec<i32>{use std::collections::VecDeque; if nums.is_empty(){return vec![];} let mut d:VecDeque<usize>=VecDeque::new(); let mut o=Vec::with_capacity(nums.len()-k+1); for i in 0..nums.len(){while let Some(&b)=d.back(){if nums[b]<=nums[i]{d.pop_back();}else{break}} d.push_back(i); if d[0]+k<=i{d.pop_front();} if i+1>=k{o.push(nums[d[0]]);}} o}
pub fn vhgw(nums:&[i32],k:usize)->Vec<i32>{ let n=nums.len(); if n==0{return vec![];} if k==1{return nums.to_vec();} let mut suf=vec![0i32;n]; let mut i=n; while i>0{ i-=1; suf[i]= if i%k==k-1 || i==n-1 {nums[i]} else {nums[i].max(suf[i+1])}; } let mut o=Vec::with_capacity(n-k+1); let mut pre=i32::MIN; for j in 0..n{ if j%k==0{pre=nums[j];} else {pre=pre.max(nums[j]);} if j+1>=k{ o.push(suf[j+1-k].max(pre)); } } o }
